package com.wiktor.jogger;
import org.json.*;
import java.io.*;
import java.net.URLEncoder;
import java.nio.file.*;
import java.util.*;

public final class Content {
 private static final String API="https://api.modrinth.com/v2/";
 private static String enc(String s)throws Exception{return URLEncoder.encode(s,"UTF-8");}
 public static JSONArray search(String query,String version,String loader,boolean packs)throws Exception{JSONArray facets=new JSONArray().put(new JSONArray().put("project_type:"+(packs?"resourcepack":"mod"))).put(new JSONArray().put("versions:"+version));if(!packs&&!loader.equals("Vanilla"))facets.put(new JSONArray().put("categories:"+loader.toLowerCase(Locale.ROOT)));return new JSONObject(Core.fetch(API+"search?limit=25&query="+enc(query)+"&facets="+enc(facets.toString()))).getJSONArray("hits");}
 private static boolean contains(JSONArray a,String s){if(a==null)return false;for(int i=0;i<a.length();i++)if(a.optString(i).equals(s))return true;return false;}
 private static JSONObject choose(String project,String version,String loader,boolean packs)throws Exception{String q="?game_versions="+enc(new JSONArray().put(version).toString());if(!packs)q+="&loaders="+enc(new JSONArray().put(loader.toLowerCase(Locale.ROOT)).toString());JSONArray a=new JSONArray(Core.fetch(API+"project/"+enc(project)+"/version"+q));if(a.length()==0)throw new IOException("No compatible file for "+project);return a.getJSONObject(0);}
 private static void resolve(JSONObject v,String version,String loader,boolean packs,Map<String,JSONObject> selected,Set<String> visiting)throws Exception{
  String project=v.getString("project_id"),id=v.getString("id");JSONObject old=selected.get(project);if(old!=null){if(!old.getString("id").equals(id))throw new IOException("Conflicting required versions for "+project);return;}if(!contains(v.getJSONArray("game_versions"),version))throw new IOException("Dependency has incompatible Minecraft version");if(!packs&&!contains(v.getJSONArray("loaders"),loader.toLowerCase(Locale.ROOT)))throw new IOException("Dependency uses a different loader");if(visiting.size()>64)throw new IOException("Too many dependencies");if(!visiting.add(id))return;selected.put(project,v);JSONArray deps=v.optJSONArray("dependencies");if(deps!=null)for(int i=0;i<deps.length();i++){JSONObject d=deps.getJSONObject(i);if(!d.optString("dependency_type").equals("required"))continue;JSONObject child=!d.isNull("version_id")?new JSONObject(Core.fetch(API+"version/"+enc(d.getString("version_id")))):choose(d.getString("project_id"),version,loader,packs);resolve(child,version,loader,packs,selected,visiting);}visiting.remove(id);
 }
 public static void install(String project,JSONObject instance,File dir,boolean packs,Core.Progress p)throws Exception{
  if(!packs&&instance.optString("loader").equals("Vanilla"))throw new IOException("Create a Fabric or Quilt instance before installing mods");String version=instance.getString("version"),loader=instance.getString("loader");Map<String,JSONObject> chosen=new LinkedHashMap<>();resolve(choose(project,version,loader,packs),version,loader,packs,chosen,new HashSet<>());
  File destination=new File(dir,packs?"resourcepacks":"mods"),stage=new File(dir,".download-"+UUID.randomUUID());destination.mkdirs();stage.mkdirs();Map<File,File>ready=new LinkedHashMap<>();List<File>published=new ArrayList<>();Map<File,File>backups=new LinkedHashMap<>();try{for(JSONObject v:chosen.values()){JSONArray files=v.getJSONArray("files");JSONObject chosenFile=null;for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);if(chosenFile==null||f.optBoolean("primary"))chosenFile=f;}if(chosenFile==null)throw new IOException("Project has no files");String name=safeName(chosenFile.getString("filename"),packs);File temp=Core.inside(stage,name),dest=Core.inside(destination,name);if(ready.containsValue(dest))throw new IOException("Two dependencies use the same filename");p.update("Downloading "+name);String hash=chosenFile.getJSONObject("hashes").getString("sha512");Core.download(chosenFile.getString("url"),temp,hash,"SHA-512");Core.archive(temp,packs);ready.put(temp,dest);}Core.check();for(Map.Entry<File,File>e:ready.entrySet()){File dest=e.getValue();if(dest.exists()){File old=new File(stage,dest.getName()+".previous");Files.move(dest.toPath(),old.toPath());backups.put(dest,old);}Files.move(e.getKey().toPath(),dest.toPath(),StandardCopyOption.ATOMIC_MOVE);published.add(dest);}p.update("Installed "+ready.size()+" verified file(s)");}catch(Exception e){for(File f:published)f.delete();for(Map.Entry<File,File>b:backups.entrySet())Files.move(b.getValue().toPath(),b.getKey().toPath(),StandardCopyOption.REPLACE_EXISTING);throw e;}finally{File[]fs=stage.listFiles();if(fs!=null)for(File f:fs)f.delete();stage.delete();}
 }
 public static String safeName(String name,boolean packs)throws IOException{String n=new File(name).getName();if(!n.equals(name)||n.contains("\\")||n.length()>180||!n.toLowerCase(Locale.ROOT).endsWith(packs?".zip":".jar"))throw new IOException("Expected a safe "+(packs?"ZIP":"JAR")+" filename");return n;}
 public static void fromUrl(String url,String name,File dir,boolean packs)throws Exception{String n=safeName(name,packs);File target=Core.inside(new File(dir,packs?"resourcepacks":"mods"),n),stage=new File(dir,"import-"+UUID.randomUUID()+".tmp");try{Core.download(url,stage,null,"SHA-256");Core.archive(stage,packs);target.getParentFile().mkdirs();if(target.exists())throw new IOException("File already exists: "+n);Files.move(stage.toPath(),target.toPath(),StandardCopyOption.ATOMIC_MOVE);}finally{stage.delete();}}
}
